// Normalize input
const all = $input.all().map(i => i.json);
let items = all;
if (all.length === 1 && !all[0].title) {
  const o = all[0];
  items = o.items || o.news || o.data || Object.values(o).find(Array.isArray) || [];
}
if (!Array.isArray(items)) items = [];

const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
store.initialized = !!store.initialized;
const firstRun = !store.initialized;
const out = [];

function normalizeId(item) {
  const url = String(item.source_url || item.url || '').trim();
  if (url) {
    try {
      const u = new URL(url);
      u.hash = '';
      ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','fbclid','gclid']
        .forEach(p => u.searchParams.delete(p));
      return u.toString();
    } catch {}
  }
  return String(item.title || '').trim().toLowerCase();
}

function cleanText(value) {
  if (!value) return '';
  const text = String(value).replace(/\s+/g, ' ').trim();
  const markers = [
    'English العربية UN Logo','العربية UN Logo',
    'ابحث عن بيانات الأمم المتحدة','من نحن عن الأمم المتحدة',
    'Submit search','مسار التنقل','المركز الإعلامي'
  ];
  const count = markers.filter(m => text.includes(m)).length;
  if (count >= 2) return '';
  if (text.length > 700 && count >= 1) return '';
  return text;
}

function getSummary(item) {
  const candidates = [
    item.summary,item.description,item.ai_summary_ar,
    item.what_happened_ar,
    Array.isArray(item.facts_ar) ? item.facts_ar[0] : ''
  ];
  for (const value of candidates) {
    const clean = cleanText(value);
    if (clean) return clean.slice(0,500);
  }
  return '';
}

function classify(item) {
  const status = String(item.status || '').toLowerCase();
  const confidence = String(item.confidence || '').toLowerCase();
  const platform = String(item.platform || 'news').toLowerCase();

  if (status === 'published' &&
      (confidence === 'high' || confidence === 'medium') &&
      platform === 'news') return 'published';

  if (status === 'review') return 'review';

  return null;
}

for (const item of items) {
  const id = normalizeId(item);
  if (!id) continue;

  const route = classify(item);
  const currentStatus = String(item.status || '').toLowerCase();

  const previous = store.seen[id] || {
    lastStatus:null,
    lastRoute:null,
    lastSentAt:0
  };

  // Ignore states that are not distributable
  if (!route) {
    previous.lastStatus = currentStatus;
    store.seen[id] = previous;
    continue;
  }

  // Do not resend the same state, but allow review -> published
  const alreadySentSameState =
    previous.lastRoute === route &&
    previous.lastStatus === currentStatus;

  if (alreadySentSameState) {
    store.seen[id] = previous;
    continue;
  }

  const title = cleanText(item.title) || 'بدون عنوان';
  const summary = getSummary(item);
  const src = cleanText(item.source_name) || cleanText(item.source) || 'غير محدد';
  const link = String(item.source_url || item.url || '').trim();

  if (route === 'published') {
    out.push({json:{
      route:'published',
      id,
      text:`🟢 ${title}

${summary}

المصدر: ${src}
${link}`
    }});
  }

  if (route === 'review') {
    out.push({json:{
      route:'review',
      id,
      text:`🔎 قيد التحقق
لا يُنشر كخبر مؤكد

${title}

${summary}

المصدر: ${src}
${link}`
    }});
  }

  previous.lastStatus = currentStatus;
  previous.lastRoute = route;
  previous.lastSentAt = Date.now();
  store.seen[id] = previous;
}

// Bound static state
const keys = Object.keys(store.seen);
if (keys.length > 2000) {
  keys.sort((a,b) => (store.seen[a]?.lastSentAt||0) - (store.seen[b]?.lastSentAt||0))
    .slice(0, keys.length - 2000)
    .forEach(k => delete store.seen[k]);
}

// Freshness alert
const times = items
  .filter(i => String(i.status || '').toLowerCase() === 'published' && i.published)
  .map(i => new Date(i.published).getTime())
  .filter(t => !isNaN(t));

if (times.length) {
  const newest = Math.max(...times);
  const ageH = (Date.now() - newest) / 3600000;
  const lastAlert = store.lastStaleAlert || 0;

  if (ageH > 4 && Date.now() - lastAlert > 4 * 3600000) {
    store.lastStaleAlert = Date.now();
    out.push({json:{
      route:'stale',
      text:`⚠️ تنبيه الثورة الجنوبية

لا توجد أخبار منشورة جديدة منذ ${ageH.toFixed(1)} ساعة

راجع GitHub Actions وnews_bot_v2.py`
    }});
  }
}

store.initialized = true;
return out;
